CREATE TABLE IF NOT EXISTS compliance_controls(control_id TEXT PRIMARY KEY,framework TEXT NOT NULL,statement TEXT NOT NULL,owner TEXT NOT NULL,status TEXT NOT NULL,evidence_ids_json TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS attestations(attestation_id TEXT PRIMARY KEY,control_id TEXT NOT NULL,attestor TEXT NOT NULL,conclusion TEXT NOT NULL,evidence_ids_json TEXT NOT NULL,signed_at TEXT NOT NULL);